"""Fuse lexical and dense ranks without comparing unlike raw scores."""

RRF_K = 60

def reciprocal_rank_fusion(lexical_rank, dense_rank):
    """Return sum(1 / (RRF_K + rank)) for each present one-based rank."""
    score = 0.0
    for rank in (lexical_rank, dense_rank):
        if rank is not None:
            score += 1.0 / (RRF_K + rank)
    return score

"""Accept a fixed one-shot JSON operation; never execute request text."""

import subprocess

OPERATIONS = {"index", "search"}
MAX_REQUEST_BYTES = 16 * 1024

def start_worker(python_exe, worker_file, request_json):
    """Use fixed argv, stdin JSON, shell=False, bounded output, and a timeout."""
    return subprocess.run(
        [python_exe, "-I", worker_file], input=request_json, capture_output=True,
        timeout=120, check=False, shell=False
    )

"""Apply the allowlist and secret exclusions before indexing workspace text."""

EXCLUDED_DIRS = {".git", ".venv", "build", "node_modules"}
SENSITIVE_NAMES = {"credentials.json", "secrets.json", "id_rsa"}

def eligible(path, text):
    """Reject hidden paths, non-allowlisted suffixes, links, and secret patterns."""
    if has_hidden_component(path) or excluded_directory(path):
        return False
    return allowed_text_suffix(path) and not sensitive_content(text)

"""Keep active generations and every retrieval operation project-scoped."""

import hashlib

def stable_project_id(canonical_local_root):
    """Hash a normalized selected root; never merge rows across project IDs."""
    return "workspace-" + hashlib.sha256(canonical_local_root.encode()).hexdigest()

def search(database, project_id, query):
    """Read only the active generation whose project_id matches this request."""
    return database.active_chunks(project_id, query)

"""Write short structured lifecycle events without source text."""

EVENT_LEVELS = {"debug", "info", "warning", "error"}

def record_event(event_name, correlation_id):
    """Persist only an allowlisted event name and opaque correlation identifier."""
    return {"event": validate_name(event_name), "correlation_id": correlation_id}

"""Report health for a locally launched model runtime process."""

def health_status(process):
    """Return running, stopped, or unknown from process state and heartbeat age."""
    if process.exited:
        return "stopped"
    return "running" if process.heartbeat_is_fresh else "unknown"
